import assert from 'node:assert/strict';
import test from 'node:test';
import { merge } from '../src/accounts/merge.js';

const store = accounts => ({ get: id => accounts[id] });

test('a support lead can merge', () => {
  const accounts = { a: { orders: [1], disputes: [] }, b: { orders: [2], disputes: [] } };
  merge(store(accounts), 'a', 'b', { roles: ['support-lead'] });
  assert.deepEqual(accounts.a.orders, [1, 2]);
});

// AC-3 (R-3): Given an account with an open dispute, when a support lead
// merges it, then the merge is refused and nothing moves.
const accountsWithOpenDisputeOn = side => {
  const openDispute = [{ id: 'd1', status: 'open' }];
  return {
    a: {
      orders: [1],
      addresses: ['1 Old Street'],
      notes: ['older note'],
      disputes: side === 'older' ? openDispute : [],
    },
    b: {
      orders: [2],
      addresses: ['2 New Street'],
      notes: ['newer note'],
      disputes: side === 'newer' ? openDispute : [],
    },
  };
};

for (const side of ['newer', 'older']) {
  test(`AC-3: a merge is refused and nothing moves when the ${side} account has an open dispute`, () => {
    const accounts = accountsWithOpenDisputeOn(side);
    const before = structuredClone(accounts);

    assert.throws(() => merge(store(accounts), 'a', 'b', { roles: ['support-lead'] }));
    assert.deepEqual(accounts, before);
  });
}
